const inp = $input.first().json;

const required = ['intent', 'cliente_id', 'cliente_whatsapp'];
const missing = required.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { _error: 'inputs_incompletos', missing, ...inp } }];
}

const valid_intents = ['reprogramar', 'cancelar', 'confirmar_otp'];
if (!valid_intents.includes(inp.intent)) {
  return [{ json: { _error: 'intent_invalido', intent: inp.intent } }];
}

return [{
  json: {
    intent: inp.intent,
    cliente_id: inp.cliente_id,
    cliente_whatsapp: inp.cliente_whatsapp,
    datos: inp.datos || {},
    p1: inp.cliente_id,  // para queries
  }
}];

const ctx = $input.first().json.ctx || $input.first().json;
const params = $('Validar inputs').first().json;
return [{
  json: {
    ...params,
    contexto: ctx,
    rama: params.intent  // 'reprogramar' | 'cancelar' | 'confirmar_otp'
  }
}];

const ctx = $json.contexto;
const params = $json;
const datos = params.datos || {};

if (!ctx.cita_activa) {
  return [{ json: { ok: false, motivo: 'sin_cita_activa', ...params } }];
}

if ((ctx.cliente?.contador_reprogramaciones || 0) >= 3) {
  return [{ json: { ok: false, motivo: 'limite_reprogramaciones', ...params, cita_activa: ctx.cita_activa } }];
}

// Validar que el cliente especificó nueva fecha + hora (sede asume la actual)
if (!datos.fecha_solicitada || !datos.hora_solicitada) {
  return [{ json: { ok: false, motivo: 'datos_faltantes', ...params, cita_activa: ctx.cita_activa, faltantes: ['fecha', 'hora'].filter(k => !datos[`${k}_solicitada`]) } }];
}

// Construir nuevo slot ISO
const fecha = datos.fecha_solicitada;
const hora = datos.hora_solicitada.length === 5 ? datos.hora_solicitada + ':00' : datos.hora_solicitada;
const nuevo_slot_iso = `${fecha}T${hora}-05:00`;
const slotDate = new Date(nuevo_slot_iso);
if (Number.isNaN(slotDate.getTime()) || slotDate < new Date()) {
  return [{ json: { ok: false, motivo: 'fecha_invalida', ...params, cita_activa: ctx.cita_activa } }];
}

return [{
  json: {
    ok: true,
    cita_vieja_id: ctx.cita_activa.id,
    terapeuta_id: ctx.cita_activa.terapeuta_id,
    sede_id: ctx.cita_activa.sede_id,
    servicio_id: ctx.cita_activa.servicio_id,
    duracion_minutos: ctx.cita_activa.duracion_minutos,
    servicio_nombre: ctx.cita_activa.servicio_nombre,
    terapeuta_nombre: ctx.cita_activa.terapeuta_nombre,
    sede_nombre: ctx.cita_activa.sede_nombre,
    nuevo_slot_iso,
    fecha,
    cliente_id: params.cliente_id,
    cliente_whatsapp: params.cliente_whatsapp,
  }
}];

const ctx = $input.first().json.ctx || $input.first().json;
const params = $('Validar reprogramar').first().json;

if (!ctx.terapeuta) {
  return [{ json: { ok: false, motivo: 'terapeuta_no_encontrado', ...params } }];
}

const slotIni = new Date(params.nuevo_slot_iso);
const slotFin = new Date(slotIni.getTime() + params.duracion_minutos * 60_000);
const DIAS = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];

const fechaBogota = params.fecha;
const horaInicioBogota = params.nuevo_slot_iso.split('T')[1].substring(0, 5);
const [diaY, diaM, diaD] = fechaBogota.split('-').map(Number);
const refDate = new Date(Date.UTC(diaY, diaM - 1, diaD, 12));
const diaSemana = DIAS[refDate.getUTCDay()];
const [hI, mI] = horaInicioBogota.split(':').map(Number);
const slotMinIni = hI * 60 + mI;
const slotMinFin = slotMinIni + params.duracion_minutos;

function dentroHorario(hb) {
  const franjas = (hb || {})[diaSemana] || [];
  if (!franjas.length) return false;
  return franjas.some(({inicio, fin}) => {
    const [fhi, fmi] = inicio.split(':').map(Number);
    const [fhf, fmf] = fin.split(':').map(Number);
    return slotMinIni >= fhi*60+fmi && slotMinFin <= fhf*60+fmf;
  });
}
function solapa(aI, aF, bI, bF) { return aI < bF && bI < aF; }

const t = ctx.terapeuta;
if (!dentroHorario(t.horario_base)) {
  return [{ json: { ok: false, motivo: 'fuera_horario', ...params, terapeuta_nombre: t.nombre } }];
}
for (const c of (ctx.citas_dia || [])) {
  if (c.id === params.cita_vieja_id) continue;  // ignorar la cita vieja (será reprogramada)
  if (solapa(slotIni, slotFin, new Date(c.slot_inicio), new Date(c.slot_fin))) {
    return [{ json: { ok: false, motivo: 'ocupado', ...params } }];
  }
}
for (const b of (ctx.bloqueos_dia || [])) {
  if (solapa(slotIni, slotFin, new Date(b.inicio), new Date(b.fin))) {
    return [{ json: { ok: false, motivo: 'bloqueo', ...params } }];
  }
}

return [{
  json: {
    ok: true,
    nuevo_slot_inicio: slotIni.toISOString(),
    nuevo_slot_fin: slotFin.toISOString(),
    ...params,
  }
}];

const ctx = $json.contexto;
const params = $json;

if (!ctx.cita_activa) {
  return [{ json: { ok: false, motivo: 'sin_cita_activa', ...params } }];
}

return [{
  json: {
    ok: true,
    cita_id: ctx.cita_activa.id,
    cita_activa: ctx.cita_activa,
    cliente_whatsapp: params.cliente_whatsapp,
  }
}];

const ctx = $json.contexto;
const params = $json;
const datos = params.datos || {};

if (!ctx.cita_pendiente_otp) {
  return [{ json: { ok: false, motivo: 'sin_otp_pendiente', ...params } }];
}

const otpEsperado = ctx.cita_pendiente_otp.otp_code;
const otpRecibido = (datos.otp_recibido || '').trim();

if (otpRecibido !== otpEsperado) {
  return [{ json: { ok: false, motivo: 'otp_incorrecto', otp_recibido: otpRecibido, ...params } }];
}

if (new Date(ctx.cita_pendiente_otp.otp_expira_at) < new Date()) {
  return [{ json: { ok: false, motivo: 'otp_expirado', ...params } }];
}

return [{
  json: {
    ok: true,
    cita_id: ctx.cita_pendiente_otp.id,
    cliente_whatsapp: params.cliente_whatsapp,
  }
}];

const r = $input.first().json;
const params = $('Validar inputs').first().json;
let text;

// Reprog OK
if (r.cita_nueva_id) {
  const fecha = new Date(r.slot_inicio).toLocaleString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit', timeZone: 'America/Bogota' });
  text = `✨ Reprogramación confirmada — Zoe Tantric SPA\n\n📅 ${fecha}\n\nLlevas ${r.contador_actual}/3 reprogramaciones de esta cita.`;
}
// Cancelar OK
else if (r.id && params.intent === 'cancelar') {
  text = `Tu cita fue cancelada. Si quieres reagendar, escríbenos cuando puedas. 🙏`;
}
// Confirmar OTP OK
else if (r.id && params.intent === 'confirmar_otp') {
  text = `✅ Validación recibida. Gracias por tu visita a Zoe. ¡Esperamos verte pronto! 🌿`;
}
// Reprog fail
else if (r.motivo === 'limite_reprogramaciones') {
  text = `Hemos alcanzado el límite de 3 reprogramaciones para tu reserva. Una persona del equipo te contactará para coordinar.`;
}
else if (r.motivo === 'sin_cita_activa') {
  text = `No encontré una cita activa para reprogramar/cancelar. ¿Quieres que te ayude con algo más?`;
}
else if (r.motivo === 'datos_faltantes') {
  text = `Para reprogramar necesito la nueva fecha y hora. ¿Me las pasas?`;
}
else if (r.motivo === 'fecha_invalida') {
  text = `La fecha que me diste no es válida o ya pasó. ¿Probamos con otra?`;
}
else if (r.motivo === 'fuera_horario' || r.motivo === 'ocupado' || r.motivo === 'bloqueo') {
  text = `${r.terapeuta_nombre || 'Tu terapeuta'} no está disponible a esa hora. ¿Probamos otro horario?`;
}
else if (r.motivo === 'sin_otp_pendiente') {
  text = `No tienes ningún código pendiente de validación.`;
}
else if (r.motivo === 'otp_incorrecto') {
  text = `Ese código no coincide. Revisa el último mensaje y vuelve a enviarlo, por favor.`;
}
else if (r.motivo === 'otp_expirado') {
  text = `Tu código de validación expiró. Si tu sesión sí ocurrió, escríbenos para corregir el registro. 🙏`;
}
else {
  text = `Algo no salió bien (${r.motivo || 'desconocido'}). Una persona del equipo te contacta.`;
}

const notificar_admin = ['limite_reprogramaciones', 'otp_expirado'].includes(r.motivo) || (r.cita_nueva_id && r.contador_actual >= 3);

return [{
  json: {
    text_cliente: text,
    notificar_admin,
    cliente_whatsapp: params.cliente_whatsapp,
    cliente_id: params.cliente_id,
    intent: params.intent,
    motivo: r.motivo || 'ok',
  }
}];

